CREATE TABLE IF NOT EXISTS capital_structure (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, jurisdiction text NOT NULL DEFAULT 'Nigeria', authorized_share_capital numeric, nominal_value_per_share numeric, currency text NOT NULL DEFAULT 'NGN', share_class text NOT NULL, authorized_shares numeric, issued_shares numeric DEFAULT 0, treasury_shares numeric DEFAULT 0, voting_rights text, dividend_rights text, status text NOT NULL DEFAULT 'Draft / Needs Verification', evidence_reference text, effective_date date, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS capital_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, event_type text NOT NULL, event_date date, share_class text, shares_affected numeric, price_per_share numeric, currency text DEFAULT 'NGN', counterparty text, approval_status text NOT NULL DEFAULT 'Pending Approval', status text NOT NULL DEFAULT 'Draft', instrument_reference text, board_resolution_reference text, shareholder_resolution_reference text, filing_reference text, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS share_ledger (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, holder_name text NOT NULL, holder_type text NOT NULL, share_class text NOT NULL, shares numeric NOT NULL DEFAULT 0, voting_rights text, acquisition_event_id uuid REFERENCES capital_events(id), acquisition_date date, transfer_restriction text, beneficial_owner text, verification_status text NOT NULL DEFAULT 'Unverified', evidence_reference text, status text NOT NULL DEFAULT 'Active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS equity_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, plan_name text NOT NULL, participant_type text NOT NULL DEFAULT 'Employee', instrument_type text NOT NULL, pool_size numeric, vesting_rule text, exercise_rule text, approval_status text NOT NULL DEFAULT 'Concept / Needs Legal Review', status text NOT NULL DEFAULT 'Draft', jurisdiction text DEFAULT 'Nigeria', notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ownership_snapshots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, snapshot_date date NOT NULL, share_class text NOT NULL, holder_name text NOT NULL, holder_type text NOT NULL, shares numeric NOT NULL, ownership_percent numeric, voting_percent numeric, source_event_id uuid REFERENCES capital_events(id), verification_status text NOT NULL DEFAULT 'Unverified', evidence_reference text, created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO equity_plans(entity_name,plan_name,participant_type,instrument_type,pool_size,vesting_rule,exercise_rule,notes) SELECT 'OSANVAULT AFRICA LTD','Future Employee Equity Framework','Employee / Key Talent','To be determined — options, restricted shares or other lawful instrument',0,'To be defined after legal/tax review','To be defined after legal/tax review','Framework reserved for future employees; no equity has been granted or promised by this record.' WHERE NOT EXISTS (SELECT 1 FROM equity_plans WHERE plan_name='Future Employee Equity Framework');